<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../auth/otp-mail.php'; methodOnly('POST'); safeApi(function():void{$email=strtolower(inputString(jsonRequest(),'email',true));if(!filter_var($email,FILTER_VALIDATE_EMAIL))jsonResponse(false,'Please provide a valid email address.',null,[],422);$db=apiDatabase();$q=$db->prepare("SELECT id FROM customers WHERE email=:email AND status='ACTIVE' LIMIT 1");$q->execute([':email'=>$email]);$c=$q->fetch();if(!$c)jsonResponse(true,'If an account exists, a verification code has been sent.',null);$q=$db->prepare("SELECT created_at FROM customer_email_otps WHERE email=:email AND purpose='PASSWORD_RESET' ORDER BY id DESC LIMIT 1");$q->execute([':email'=>$email]);$last=$q->fetch();if($last&&strtotime($last['created_at'])>time()-60)jsonResponse(true,'If an account exists, a verification code has been sent.',null);$otp=(string)random_int(100000,999999);$db->beginTransaction();$db->prepare("UPDATE customer_email_otps SET used_at=NOW() WHERE email=:email AND purpose='PASSWORD_RESET' AND used_at IS NULL")->execute([':email'=>$email]);$db->prepare("INSERT INTO customer_email_otps(email,otp_hash,purpose,expires_at) VALUES(:email,:hash,'PASSWORD_RESET',DATE_ADD(NOW(),INTERVAL 10 MINUTE))")->execute([':email'=>$email,':hash'=>password_hash($otp,PASSWORD_DEFAULT)]);$db->commit();if(!sendCustomerPasswordResetEmail($email,$otp))jsonResponse(false,'We could not send the verification email. Please try again.',null,[],503);jsonResponse(true,'If an account exists, a verification code has been sent.',null);});
